<?php

declare(strict_types=1);

use Componenta\Image\ConversionException;
use Componenta\Image\GdPngConverter;

// Independently encoded with libavif 1.2.1, 16x8 RGB test pattern, sRGB.
// Display properties are real, associated BMFF properties, not byte-string markers.
test('rejects AVIF display transformations that GD cannot preserve', function (string $fixture): void {
    $codec = new GdPngConverter();
    if (!$codec->supports('image/avif')) {
        $this->markTestSkipped('AVIF decoding is unavailable.');
    }
    $source = base64_decode($fixture, true);
    expect($source)->toBeString();
    $info = getimagesizefromstring($source);
    expect($info['mime'])->toBe('image/avif');
    expect([$info[0], $info[1]])->toBe([16, 8]);
    expect(imagecreatefromstring($source))->toBeInstanceOf(GdImage::class);
    expect(fn() => $codec->convert($source))->toThrow(ConversionException::class, 'AVIF display transformation');
})->with([
    'rot90' => '',
    'mirror' => '',
    'crop' => '',
    'pasp' => '',
]);

test('identity AVIF display properties are accepted', function (string $fixture): void {
    $codec = new GdPngConverter();
    if (!$codec->supports('image/avif')) {
        $this->markTestSkipped('AVIF decoding is unavailable.');
    }
    $source = base64_decode($fixture, true);
    $result = $codec->convert($source);
    $output = imagecreatefromstring($result->content);
    expect($output)->toBeInstanceOf(GdImage::class);
    expect([imagesx($output), imagesy($output)])->toBe([16, 8]);
})->with([
    'rot0' => '',
    'pasp1' => '',
]);
